s.hd("CREATE TABLE dual (dummy VARCHAR2(1));\nINSERT INTO dual VALUES ('X');\n\nCREATE TABLE services (\n  id_service NUMBER(4)    CONSTRAINT pk_services PRIMARY KEY,\n  nom        VARCHAR2(50) NOT NULL,\n  ville      VARCHAR2(50)\n);\n\nCREATE TABLE employes (\n  id_employe    NUMBER(6)     CONSTRAINT pk_employes PRIMARY KEY,\n  nom           VARCHAR2(50)  NOT NULL,\n  prenom        VARCHAR2(50),\n  email         VARCHAR2(100) CONSTRAINT uq_emp_email UNIQUE,\n  salaire       NUMBER(10)    CONSTRAINT ck_emp_salaire CHECK (salaire > 0),\n  prime         NUMBER(10),\n  date_embauche DATE          DEFAULT CURRENT_TIMESTAMP NOT NULL,\n  id_service    NUMBER(4)     CONSTRAINT fk_emp_service REFERENCES services (id_service),\n  id_manager    NUMBER(6)     CONSTRAINT fk_emp_manager REFERENCES employes (id_employe)\n);\n\nINSERT INTO services VALUES (10, 'Direction', 'Yaound\xe9');\nINSERT INTO services VALUES (20, 'Informatique', 'Douala');\nINSERT INTO services VALUES (30, 'Comptabilit\xe9', 'Douala');\nINSERT INTO services VALUES (40, 'Commercial', 'Garoua');\n\nINSERT INTO employes VALUES (1, 'MBARGA', 'Paul',    'p.mbarga@exemple.cm', 1500000, NULL,   '2010-02-01 00:00:00', 10, NULL);\nINSERT INTO employes VALUES (2, 'NGO',    'A\xefcha',   'a.ngo@exemple.cm',     900000, 100000, '2015-09-14 00:00:00', 20, 1);\nINSERT INTO employes VALUES (3, 'FOTSO',  'Jean',    'j.fotso@exemple.cm',   650000, NULL,   '2021-03-01 00:00:00', 20, 2);\nINSERT INTO employes VALUES (4, 'ATANGA', 'Marie',   'm.atanga@exemple.cm',  720000, NULL,   '2018-06-04 00:00:00', 30, 1);\nINSERT INTO employes VALUES (5, 'BELLO',  'Ibrahim', NULL,                   480000, 50000,  '2023-11-20 00:00:00', 40, 1);\n")
s.hd("CREATE TABLE \"v$version\" (banner VARCHAR2(100));\nINSERT INTO \"v$version\" VALUES ('Oracle Database 19c Enterprise Edition Release 19.0.0.0.0 - Production');\n\nCREATE TABLE \"v$instance\" (instance_name VARCHAR2(16), host_name VARCHAR2(64), version VARCHAR2(17),\n  version_full VARCHAR2(17), startup_time DATE, status VARCHAR2(12), database_status VARCHAR2(17),\n  archiver VARCHAR2(7), logins VARCHAR2(10));\nINSERT INTO \"v$instance\" VALUES ('PRODCM', 'srv-ora-prod01', '19.0.0.0.0', '19.21.0.0.0',\n  '2026-10-12 06:05:11', 'OPEN', 'ACTIVE', 'STARTED', 'ALLOWED');\n\nCREATE TABLE \"v$database\" (dbid NUMBER, name VARCHAR2(9), created DATE, log_mode VARCHAR2(12),\n  open_mode VARCHAR2(20), database_role VARCHAR2(16), platform_name VARCHAR2(101), flashback_on VARCHAR2(18),\n  cdb VARCHAR2(3));\nINSERT INTO \"v$database\" VALUES (2418836512, 'PRODCM', '2019-04-08 10:22:41', 'ARCHIVELOG', 'READ WRITE',\n  'PRIMARY', 'Linux x86 64-bit', 'NO', 'NO');\n\nCREATE TABLE \"v$parameter\" (name VARCHAR2(80), value VARCHAR2(512), isdefault VARCHAR2(9), ismodified VARCHAR2(10));\nINSERT INTO \"v$parameter\" VALUES\n  ('db_name', 'PRODCM', 'FALSE', 'FALSE'),\n  ('db_block_size', '8192', 'FALSE', 'FALSE'),\n  ('compatible', '19.0.0', 'FALSE', 'FALSE'),\n  ('memory_target', '0', 'TRUE', 'FALSE'),\n  ('sga_target', '8589934592', 'FALSE', 'FALSE'),\n  ('sga_max_size', '8589934592', 'FALSE', 'FALSE'),\n  ('pga_aggregate_target', '2147483648', 'FALSE', 'FALSE'),\n  ('pga_aggregate_limit', '4294967296', 'FALSE', 'FALSE'),\n  ('processes', '600', 'FALSE', 'FALSE'),\n  ('sessions', '924', 'TRUE', 'FALSE'),\n  ('open_cursors', '300', 'FALSE', 'FALSE'),\n  ('undo_management', 'AUTO', 'TRUE', 'FALSE'),\n  ('undo_tablespace', 'UNDOTBS1', 'FALSE', 'FALSE'),\n  ('undo_retention', '900', 'TRUE', 'FALSE'),\n  ('control_files', '/u02/oradata/PRODCM/control01.ctl, /u03/fra/PRODCM/control02.ctl', 'FALSE', 'FALSE'),\n  ('db_recovery_file_dest', '/u03/fra', 'FALSE', 'FALSE'),\n  ('db_recovery_file_dest_size', '107374182400', 'FALSE', 'FALSE'),\n  ('log_archive_dest_1', 'LOCATION=USE_DB_RECOVERY_FILE_DEST', 'FALSE', 'FALSE'),\n  ('audit_trail', 'DB', 'FALSE', 'FALSE'),\n  ('remote_login_passwordfile', 'EXCLUSIVE', 'TRUE', 'FALSE'),\n  ('diagnostic_dest', '/u01/app/oracle', 'FALSE', 'FALSE'),\n  ('optimizer_mode', 'ALL_ROWS', 'TRUE', 'FALSE'),\n  ('cursor_sharing', 'EXACT', 'TRUE', 'FALSE'),\n  ('control_management_pack_access', 'DIAGNOSTIC+TUNING', 'TRUE', 'FALSE'),\n  ('statistics_level', 'TYPICAL', 'TRUE', 'FALSE');\n\nCREATE TABLE \"v$sga\" (name VARCHAR2(20), value NUMBER);\nINSERT INTO \"v$sga\" VALUES ('Fixed Size', 9144232), ('Variable Size', 1946157056),\n  ('Database Buffers', 6576668672), ('Redo Buffers', 57954304);\n\nCREATE TABLE dba_tablespaces (tablespace_name VARCHAR2(30), block_size NUMBER, status VARCHAR2(9),\n  contents VARCHAR2(21), logging VARCHAR2(9), extent_management VARCHAR2(10),\n  segment_space_management VARCHAR2(6), bigfile VARCHAR2(3));\nINSERT INTO dba_tablespaces VALUES\n  ('SYSTEM', 8192, 'ONLINE', 'PERMANENT', 'LOGGING', 'LOCAL', 'MANUAL', 'NO'),\n  ('SYSAUX', 8192, 'ONLINE', 'PERMANENT', 'LOGGING', 'LOCAL', 'AUTO', 'NO'),\n  ('UNDOTBS1', 8192, 'ONLINE', 'UNDO', 'LOGGING', 'LOCAL', 'MANUAL', 'NO'),\n  ('TEMP', 8192, 'ONLINE', 'TEMPORARY', 'NOLOGGING', 'LOCAL', 'MANUAL', 'NO'),\n  ('USERS', 8192, 'ONLINE', 'PERMANENT', 'LOGGING', 'LOCAL', 'AUTO', 'NO'),\n  ('APP_DATA', 8192, 'ONLINE', 'PERMANENT', 'LOGGING', 'LOCAL', 'AUTO', 'NO'),\n  ('APP_INDEX', 8192, 'ONLINE', 'PERMANENT', 'LOGGING', 'LOCAL', 'AUTO', 'NO');\n\nCREATE TABLE dba_data_files (file_name VARCHAR2(513), file_id NUMBER, tablespace_name VARCHAR2(30),\n  bytes NUMBER, status VARCHAR2(9), autoextensible VARCHAR2(3), maxbytes NUMBER, online_status VARCHAR2(7));\nINSERT INTO dba_data_files VALUES\n  ('/u02/oradata/PRODCM/system01.dbf', 1, 'SYSTEM', 1024*1048576, 'AVAILABLE', 'YES', 32767*1048576, 'SYSTEM'),\n  ('/u02/oradata/PRODCM/sysaux01.dbf', 2, 'SYSAUX', 2048*1048576, 'AVAILABLE', 'YES', 32767*1048576, 'ONLINE'),\n  ('/u02/oradata/PRODCM/undotbs01.dbf', 3, 'UNDOTBS1', 4096*1048576, 'AVAILABLE', 'YES', 32767*1048576, 'ONLINE'),\n  ('/u02/oradata/PRODCM/users01.dbf', 4, 'USERS', 512*1048576, 'AVAILABLE', 'NO', 0, 'ONLINE'),\n  ('/u02/oradata/PRODCM/app_data01.dbf', 5, 'APP_DATA', 30*1073741824, 'AVAILABLE', 'NO', 0, 'ONLINE'),\n  ('/u02/oradata/PRODCM/app_data02.dbf', 6, 'APP_DATA', 30*1073741824, 'AVAILABLE', 'NO', 0, 'ONLINE'),\n  ('/u02/oradata/PRODCM/app_index01.dbf', 7, 'APP_INDEX', 10*1073741824, 'AVAILABLE', 'NO', 0, 'ONLINE');\n\nCREATE TABLE dba_temp_files (file_name VARCHAR2(513), file_id NUMBER, tablespace_name VARCHAR2(30),\n  bytes NUMBER, autoextensible VARCHAR2(3), maxbytes NUMBER);\nINSERT INTO dba_temp_files VALUES ('/u02/oradata/PRODCM/temp01.dbf', 1, 'TEMP', 2048*1048576, 'YES', 32767*1048576);\n\nCREATE TABLE dba_free_space (tablespace_name VARCHAR2(30), file_id NUMBER, block_id NUMBER, bytes NUMBER);\nINSERT INTO dba_free_space VALUES\n  ('SYSTEM', 1, 120000, 210*1048576),\n  ('SYSAUX', 2, 230000, 300*1048576), ('SYSAUX', 2, 250000, 80*1048576),\n  ('UNDOTBS1', 3, 1200, 3500*1048576),\n  ('USERS', 4, 800, 480*1048576),\n  ('APP_DATA', 5, 3900000, 300*1048576),\n  ('APP_DATA', 6, 3700000, 1100*1048576), ('APP_DATA', 6, 3850000, 100*1048576),\n  ('APP_INDEX', 7, 1200000, 820*1048576);\n\nCREATE TABLE dba_segments (owner VARCHAR2(128), segment_name VARCHAR2(128), segment_type VARCHAR2(18),\n  tablespace_name VARCHAR2(30), bytes NUMBER);\nINSERT INTO dba_segments VALUES\n  ('APP_VENTES', 'LIGNES_VENTES', 'TABLE', 'APP_DATA', 38000*1048576),\n  ('APP_VENTES', 'VENTES', 'TABLE', 'APP_DATA', 12000*1048576),\n  ('APP_VENTES', 'AUDIT_LOG', 'TABLE', 'APP_DATA', 8399*1048576),\n  ('APP_VENTES', 'CLIENTS', 'TABLE', 'APP_DATA', 900*1048576),\n  ('APP_RH', 'EMPLOYES', 'TABLE', 'APP_DATA', 40*1048576),\n  ('APP_RH', 'SERVICES', 'TABLE', 'APP_DATA', 1*1048576),\n  ('APP_RH', 'HISTO_PAIE', 'TABLE', 'APP_DATA', 600*1048576),\n  ('APP_VENTES', 'IDX_LIGNES_DATE', 'INDEX', 'APP_INDEX', 5600*1048576),\n  ('APP_VENTES', 'PK_LIGNES_VENTES', 'INDEX', 'APP_INDEX', 2900*1048576),\n  ('APP_VENTES', 'PK_VENTES', 'INDEX', 'APP_INDEX', 900*1048576),\n  ('APP_RH', 'PK_EMPLOYES', 'INDEX', 'APP_INDEX', 20*1048576),\n  ('SYS', 'AUD$', 'TABLE', 'SYSTEM', 310*1048576);\n\nCREATE TABLE \"v$log\" (\"group#\" NUMBER, \"thread#\" NUMBER, \"sequence#\" NUMBER, bytes NUMBER, members NUMBER,\n  archived VARCHAR2(3), status VARCHAR2(16), first_time DATE);\nINSERT INTO \"v$log\" VALUES\n  (1, 1, 48211, 200*1048576, 2, 'YES', 'INACTIVE', '2026-10-28 07:12:40'),\n  (2, 1, 48212, 200*1048576, 2, 'YES', 'ACTIVE', '2026-10-28 07:31:05'),\n  (3, 1, 48213, 200*1048576, 2, 'NO', 'CURRENT', '2026-10-28 07:48:22');\n\nCREATE TABLE \"v$logfile\" (\"group#\" NUMBER, status VARCHAR2(7), type VARCHAR2(7), member VARCHAR2(513));\nINSERT INTO \"v$logfile\" VALUES\n  (1, NULL, 'ONLINE', '/u02/oradata/PRODCM/redo01a.log'), (1, NULL, 'ONLINE', '/u03/fra/PRODCM/redo01b.log'),\n  (2, NULL, 'ONLINE', '/u02/oradata/PRODCM/redo02a.log'), (2, NULL, 'ONLINE', '/u03/fra/PRODCM/redo02b.log'),\n  (3, NULL, 'ONLINE', '/u02/oradata/PRODCM/redo03a.log'), (3, NULL, 'ONLINE', '/u03/fra/PRODCM/redo03b.log');\n\nCREATE TABLE \"v$controlfile\" (status VARCHAR2(7), name VARCHAR2(513));\nINSERT INTO \"v$controlfile\" VALUES (NULL, '/u02/oradata/PRODCM/control01.ctl'), (NULL, '/u03/fra/PRODCM/control02.ctl');\n\nCREATE TABLE \"v$session\" (sid NUMBER, \"serial#\" NUMBER, username VARCHAR2(128), status VARCHAR2(8),\n  osuser VARCHAR2(128), machine VARCHAR2(64), program VARCHAR2(48), type VARCHAR2(10), sql_id VARCHAR2(13),\n  event VARCHAR2(64), wait_class VARCHAR2(64), seconds_in_wait NUMBER, blocking_session NUMBER, logon_time DATE);\nINSERT INTO \"v$session\" VALUES\n  (2, 11021, NULL, 'ACTIVE', 'oracle', 'srv-ora-prod01', 'oracle@srv-ora-prod01 (PMON)', 'BACKGROUND', NULL, 'pmon timer', 'Idle', 3, NULL, '2026-10-12 06:05:11'),\n  (3, 30412, NULL, 'ACTIVE', 'oracle', 'srv-ora-prod01', 'oracle@srv-ora-prod01 (DBW0)', 'BACKGROUND', NULL, 'rdbms ipc message', 'Idle', 1, NULL, '2026-10-12 06:05:12'),\n  (4, 52771, NULL, 'ACTIVE', 'oracle', 'srv-ora-prod01', 'oracle@srv-ora-prod01 (LGWR)', 'BACKGROUND', NULL, 'rdbms ipc message', 'Idle', 0, NULL, '2026-10-12 06:05:12'),\n  (5, 1887, NULL, 'ACTIVE', 'oracle', 'srv-ora-prod01', 'oracle@srv-ora-prod01 (CKPT)', 'BACKGROUND', NULL, 'rdbms ipc message', 'Idle', 2, NULL, '2026-10-12 06:05:12'),\n  (6, 40330, NULL, 'ACTIVE', 'oracle', 'srv-ora-prod01', 'oracle@srv-ora-prod01 (SMON)', 'BACKGROUND', NULL, 'smon timer', 'Idle', 120, NULL, '2026-10-12 06:05:12'),\n  (7, 9015, NULL, 'ACTIVE', 'oracle', 'srv-ora-prod01', 'oracle@srv-ora-prod01 (ARC0)', 'BACKGROUND', NULL, 'Log archive I/O', 'System I/O', 0, NULL, '2026-10-12 06:05:14'),\n  (8, 22190, NULL, 'ACTIVE', 'oracle', 'srv-ora-prod01', 'oracle@srv-ora-prod01 (MMON)', 'BACKGROUND', NULL, 'rdbms ipc message', 'Idle', 4, NULL, '2026-10-12 06:05:14'),\n  (145, 52213, 'APP_RH', 'ACTIVE', 'tomcat', 'srv-app01', 'JDBC Thin Client', 'USER', '7h35uxf5uhmm1', 'enq: TX - row lock contention', 'Application', 1850, 212, '2026-10-28 06:58:02'),\n  (212, 3301, 'APP_RH', 'INACTIVE', 'jfotso', 'PC-COMPTA-07', 'SQL Developer', 'USER', NULL, 'SQL*Net message from client', 'Idle', 2400, NULL, '2026-10-27 17:42:19'),\n  (233, 61877, 'APP_RH', 'ACTIVE', 'tomcat', 'srv-app01', 'JDBC Thin Client', 'USER', '7h35uxf5uhmm1', 'enq: TX - row lock contention', 'Application', 640, 212, '2026-10-28 07:26:44'),\n  (300, 18320, 'APP_VENTES', 'ACTIVE', 'tomcat', 'srv-app02', 'JDBC Thin Client', 'USER', 'g0bggfqrddc4w', 'db file sequential read', 'User I/O', 0, NULL, '2026-10-28 07:01:10'),\n  (301, 44102, 'APP_VENTES', 'INACTIVE', 'tomcat', 'srv-app02', 'JDBC Thin Client', 'USER', NULL, 'SQL*Net message from client', 'Idle', 12, NULL, '2026-10-28 07:01:10'),\n  (302, 7765, 'APP_VENTES', 'INACTIVE', 'tomcat', 'srv-app02', 'JDBC Thin Client', 'USER', NULL, 'SQL*Net message from client', 'Idle', 35, NULL, '2026-10-28 07:01:11'),\n  (410, 12004, 'SYS', 'ACTIVE', 'oracle', 'srv-ora-prod01', 'sqlplus@srv-ora-prod01 (TNS V1-V3)', 'USER', '9babjv8yq8ru3', 'SQL*Net message to client', 'Network', 0, NULL, '2026-10-28 07:50:03'),\n  (415, 30098, 'DBSNMP', 'INACTIVE', 'oracle', 'srv-ora-prod01', 'JDBC Thin Client', 'USER', NULL, 'SQL*Net message from client', 'Idle', 48, NULL, '2026-10-12 06:20:00');\n\nCREATE TABLE dba_users (username VARCHAR2(128), user_id NUMBER, account_status VARCHAR2(32), lock_date DATE,\n  expiry_date DATE, default_tablespace VARCHAR2(30), temporary_tablespace VARCHAR2(30), profile VARCHAR2(128),\n  created DATE);\nINSERT INTO dba_users VALUES\n  ('SYS', 0, 'OPEN', NULL, NULL, 'SYSTEM', 'TEMP', 'DEFAULT', '2019-04-08 10:22:45'),\n  ('SYSTEM', 9, 'OPEN', NULL, NULL, 'SYSTEM', 'TEMP', 'DEFAULT', '2019-04-08 10:22:45'),\n  ('DBSNMP', 22, 'OPEN', NULL, NULL, 'SYSAUX', 'TEMP', 'DEFAULT', '2019-04-08 10:25:10'),\n  ('ANONYMOUS', 46, 'EXPIRED & LOCKED', '2019-04-08 10:30:00', '2019-04-08 10:30:00', 'SYSAUX', 'TEMP', 'DEFAULT', '2019-04-08 10:30:00'),\n  ('APP_RH', 110, 'OPEN', NULL, NULL, 'APP_DATA', 'TEMP', 'P_APPLI', '2019-05-02 09:00:00'),\n  ('APP_VENTES', 111, 'OPEN', NULL, NULL, 'APP_DATA', 'TEMP', 'P_APPLI', '2019-05-02 09:00:00'),\n  ('J_FOTSO', 140, 'LOCKED(TIMED)', '2026-10-28 07:40:12', '2027-01-15 00:00:00', 'USERS', 'TEMP', 'P_HUMAIN', '2021-03-01 08:30:00'),\n  ('A_NGO', 141, 'EXPIRED', NULL, '2026-10-25 00:00:00', 'USERS', 'TEMP', 'P_HUMAIN', '2015-09-14 08:30:00'),\n  ('M_ATANGA', 142, 'OPEN', NULL, '2027-02-02 00:00:00', 'USERS', 'TEMP', 'P_HUMAIN', '2018-06-04 08:30:00'),\n  ('OLD_BATCH', 120, 'OPEN', NULL, NULL, 'USERS', 'TEMP', 'DEFAULT', '2016-01-10 11:00:00');\n\nCREATE TABLE dba_profiles (profile VARCHAR2(128), resource_name VARCHAR2(32), \"limit\" VARCHAR2(128));\nINSERT INTO dba_profiles VALUES\n  ('P_HUMAIN', 'FAILED_LOGIN_ATTEMPTS', '5'), ('P_HUMAIN', 'PASSWORD_LOCK_TIME', '1/24'),\n  ('P_HUMAIN', 'PASSWORD_LIFE_TIME', '90'), ('P_HUMAIN', 'PASSWORD_GRACE_TIME', '7'),\n  ('P_APPLI', 'FAILED_LOGIN_ATTEMPTS', 'UNLIMITED'), ('P_APPLI', 'PASSWORD_LIFE_TIME', 'UNLIMITED'),\n  ('DEFAULT', 'FAILED_LOGIN_ATTEMPTS', '10'), ('DEFAULT', 'PASSWORD_LIFE_TIME', '180');\n\nCREATE TABLE dba_role_privs (grantee VARCHAR2(128), granted_role VARCHAR2(128), admin_option VARCHAR2(3),\n  default_role VARCHAR2(3));\nINSERT INTO dba_role_privs VALUES\n  ('SYS', 'DBA', 'YES', 'YES'), ('SYSTEM', 'DBA', 'YES', 'YES'),\n  ('APP_RH', 'CONNECT', 'NO', 'YES'), ('APP_RH', 'RESOURCE', 'NO', 'YES'),\n  ('APP_VENTES', 'CONNECT', 'NO', 'YES'), ('APP_VENTES', 'RESOURCE', 'NO', 'YES'),\n  ('J_FOTSO', 'CONNECT', 'NO', 'YES'), ('J_FOTSO', 'R_LECTURE_RH', 'NO', 'YES'),\n  ('A_NGO', 'CONNECT', 'NO', 'YES'), ('A_NGO', 'R_LECTURE_RH', 'NO', 'YES'),\n  ('M_ATANGA', 'CONNECT', 'NO', 'YES'), ('M_ATANGA', 'R_LECTURE_VENTES', 'NO', 'YES'),\n  ('OLD_BATCH', 'CONNECT', 'NO', 'YES'), ('OLD_BATCH', 'DBA', 'NO', 'YES');\n\nCREATE TABLE dba_sys_privs (grantee VARCHAR2(128), privilege VARCHAR2(40), admin_option VARCHAR2(3));\nINSERT INTO dba_sys_privs VALUES\n  ('APP_RH', 'UNLIMITED TABLESPACE', 'NO'), ('APP_VENTES', 'UNLIMITED TABLESPACE', 'NO'),\n  ('OLD_BATCH', 'SELECT ANY TABLE', 'NO'), ('OLD_BATCH', 'DROP ANY TABLE', 'NO'),\n  ('R_LECTURE_RH', 'CREATE SESSION', 'NO'), ('DBSNMP', 'SELECT ANY DICTIONARY', 'NO');\n\nCREATE TABLE dba_objects (owner VARCHAR2(128), object_name VARCHAR2(128), object_type VARCHAR2(23),\n  status VARCHAR2(7), last_ddl_time DATE);\nINSERT INTO dba_objects VALUES\n  ('APP_RH', 'EMPLOYES', 'TABLE', 'VALID', '2026-09-30 18:02:11'),\n  ('APP_RH', 'SERVICES', 'TABLE', 'VALID', '2025-02-11 10:00:00'),\n  ('APP_RH', 'PKG_PAIE', 'PACKAGE', 'VALID', '2026-10-27 18:15:40'),\n  ('APP_RH', 'PKG_PAIE', 'PACKAGE BODY', 'INVALID', '2026-10-27 18:15:42'),\n  ('APP_RH', 'V_ANNUAIRE', 'VIEW', 'VALID', '2024-06-01 09:00:00'),\n  ('APP_RH', 'TRG_EMP_AUDIT', 'TRIGGER', 'VALID', '2023-01-15 14:30:00'),\n  ('APP_VENTES', 'VENTES', 'TABLE', 'VALID', '2026-05-04 20:11:00'),\n  ('APP_VENTES', 'LIGNES_VENTES', 'TABLE', 'VALID', '2026-05-04 20:11:00'),\n  ('APP_VENTES', 'V_STATS_MOIS', 'VIEW', 'INVALID', '2026-10-27 18:20:03'),\n  ('APP_VENTES', 'F_TVA', 'FUNCTION', 'VALID', '2022-03-08 11:00:00'),\n  ('APP_VENTES', 'P_CLOTURE_JOUR', 'PROCEDURE', 'INVALID', '2026-10-27 18:20:05'),\n  ('OLD_BATCH', 'P_PURGE', 'PROCEDURE', 'VALID', '2016-01-10 11:30:00');\n\nCREATE TABLE \"v$recovery_file_dest\" (name VARCHAR2(513), space_limit NUMBER, space_used NUMBER,\n  space_reclaimable NUMBER, number_of_files NUMBER);\nINSERT INTO \"v$recovery_file_dest\" VALUES ('/u03/fra', 100*1073741824, 97*1073741824, 3*1073741824, 412);\n\nCREATE TABLE \"v$rman_backup_job_details\" (session_key NUMBER, start_time DATE, end_time DATE,\n  input_type VARCHAR2(13), status VARCHAR2(23), output_bytes NUMBER, elapsed_seconds NUMBER);\nINSERT INTO \"v$rman_backup_job_details\" VALUES\n  (8811, '2026-10-21 01:00:03', '2026-10-21 01:48:40', 'DB INCR', 'COMPLETED', 41*1073741824, 2917),\n  (8814, '2026-10-22 01:00:02', '2026-10-22 01:20:11', 'DB INCR', 'COMPLETED', 6*1073741824, 1209),\n  (8817, '2026-10-23 01:00:04', '2026-10-23 01:22:30', 'DB INCR', 'COMPLETED', 7*1073741824, 1346),\n  (8820, '2026-10-24 01:00:01', '2026-10-24 01:21:02', 'DB INCR', 'COMPLETED WITH WARNINGS', 6*1073741824, 1261),\n  (8823, '2026-10-25 01:00:03', '2026-10-25 01:19:55', 'DB INCR', 'COMPLETED', 5*1073741824, 1192),\n  (8826, '2026-10-26 01:00:02', '2026-10-26 01:24:18', 'DB INCR', 'COMPLETED', 7*1073741824, 1456),\n  (8829, '2026-10-27 01:00:03', '2026-10-27 01:06:41', 'DB INCR', 'FAILED', 1*1073741824, 398),\n  (8830, '2026-10-27 13:00:01', '2026-10-27 13:02:10', 'ARCHIVELOG', 'COMPLETED', 2*1073741824, 129),\n  (8832, '2026-10-28 01:00:02', '2026-10-28 01:03:12', 'DB INCR', 'FAILED', 0, 190);\n\n-- Niveau Performance --------------------------------------------------------\n\n-- Temps en microsecondes, comme dans Oracle.\nCREATE TABLE \"v$sql\" (sql_id VARCHAR2(13), plan_hash_value NUMBER, parsing_schema_name VARCHAR2(128),\n  module VARCHAR2(64), executions NUMBER, elapsed_time NUMBER, cpu_time NUMBER, buffer_gets NUMBER,\n  disk_reads NUMBER, rows_processed NUMBER, sql_text VARCHAR2(1000));\nINSERT INTO \"v$sql\" VALUES\n  ('g0bggfqrddc4w', 2836542131, 'APP_VENTES', 'caisse', 1840, 9815000000, 3120000000, 4612000000, 310400000, 220500,\n   'SELECT l.id_vente, l.produit, l.montant FROM lignes_ventes l WHERE TRUNC(l.date_vente) = :b1'),\n  ('7h35uxf5uhmm1', 1102937465, 'APP_RH', 'fiche_employe', 15230, 4120000000, 6100000, 61200, 12, 15230,\n   'UPDATE employes SET statut = :1, modifie_le = SYSDATE WHERE id_employe = :2'),\n  ('a1b2c3d4e5f6g', 3954128861, 'APP_VENTES', 'caisse', 980000, 290000000, 251000000, 3920000, 1800, 980000,\n   'SELECT c.nom, c.ville FROM clients c WHERE c.id_client = :1'),\n  ('f3k9xq2m8w1zz', 0, 'APP_VENTES', 'caisse', 2104000, 603000000, 410000000, 8500000, 0, 2104000,\n   'INSERT INTO audit_log (id, action, horodatage) VALUES (:1, :2, SYSTIMESTAMP)'),\n  ('b7m2n1q0r9s8t', 1772615004, 'APP_VENTES', 'rapport_mensuel', 3, 5410000000, 1650000000, 980000000, 120500000, 36,\n   'SELECT /* rapport mensuel */ TRUNC(v.date_vente, ''MM''), SUM(l.montant) FROM ventes v JOIN lignes_ventes l ON l.id_vente = v.id_vente GROUP BY TRUNC(v.date_vente, ''MM'')'),\n  ('0n4b2v8c7x6z1', 991827364, 'APP_VENTES', 'export_compta', 1, 41000, 39000, 5, 1, 1,\n   'SELECT * FROM ventes WHERE id_vente = 98231'),\n  ('1q7w8e9r0t2y3', 991827364, 'APP_VENTES', 'export_compta', 1, 40000, 38000, 5, 0, 1,\n   'SELECT * FROM ventes WHERE id_vente = 98232'),\n  ('2a3s4d5f6g7h8', 991827364, 'APP_VENTES', 'export_compta', 1, 43000, 40000, 5, 1, 1,\n   'SELECT * FROM ventes WHERE id_vente = 98233'),\n  ('3z4x5c6v7b8n9', 991827364, 'APP_VENTES', 'export_compta', 1, 39000, 37000, 5, 0, 1,\n   'SELECT * FROM ventes WHERE id_vente = 98234'),\n  ('9babjv8yq8ru3', 2110339421, 'SYS', 'sqlplus', 12, 150000, 140000, 900, 0, 180,\n   'SELECT sid, username, event FROM v$session WHERE type = ''USER'' ORDER BY sid');\n\n-- Un \xe9chantillon par seconde et par session active, de 9 h 00 \xe0 9 h 05.\nCREATE TABLE \"v$active_session_history\" (sample_time DATE, session_id NUMBER, sql_id VARCHAR2(13),\n  session_state VARCHAR2(7), event VARCHAR2(64), wait_class VARCHAR2(64), blocking_session NUMBER, module VARCHAR2(64));\nWITH RECURSIVE s(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM s WHERE i < 299)\nINSERT INTO \"v$active_session_history\"\nSELECT printf('2026-10-28 09:%02d:%02d', i / 60, i % 60), 300, 'g0bggfqrddc4w',\n       CASE WHEN i % 3 = 0 THEN 'ON CPU' ELSE 'WAITING' END,\n       CASE WHEN i % 3 = 0 THEN NULL ELSE 'db file scattered read' END,\n       CASE WHEN i % 3 = 0 THEN NULL ELSE 'User I/O' END, NULL, 'caisse'\nFROM s;\nWITH RECURSIVE s(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM s WHERE i < 59)\nINSERT INTO \"v$active_session_history\"\nSELECT printf('2026-10-28 09:%02d:%02d', i / 60, i % 60), 233, '7h35uxf5uhmm1', 'WAITING',\n       'enq: TX - row lock contention', 'Application', 212, 'fiche_employe'\nFROM s;\nWITH RECURSIVE s(i) AS (SELECT 0 UNION ALL SELECT i + 5 FROM s WHERE i < 295)\nINSERT INTO \"v$active_session_history\"\nSELECT printf('2026-10-28 09:%02d:%02d', i / 60, i % 60), 301, 'f3k9xq2m8w1zz', 'WAITING',\n       'log file sync', 'Commit', NULL, 'caisse'\nFROM s;\n\nCREATE TABLE \"v$system_event\" (event VARCHAR2(64), wait_class VARCHAR2(64), total_waits NUMBER,\n  time_waited_micro NUMBER);\nINSERT INTO \"v$system_event\" VALUES\n  ('db file sequential read', 'User I/O', 820000000, 492000000000),\n  ('db file scattered read', 'User I/O', 61000000, 331000000000),\n  ('log file sync', 'Commit', 240000000, 190000000000),\n  ('log file parallel write', 'System I/O', 251000000, 108000000000),\n  ('enq: TX - row lock contention', 'Application', 12400, 21300000000),\n  ('direct path read', 'User I/O', 9800000, 64000000000),\n  ('latch: shared pool', 'Concurrency', 310000, 4100000000),\n  ('SQL*Net message from client', 'Idle', 9100000000, 99000000000000),\n  ('rdbms ipc message', 'Idle', 410000000, 88000000000000);\n\nCREATE TABLE dba_indexes (owner VARCHAR2(128), index_name VARCHAR2(128), table_name VARCHAR2(128),\n  index_type VARCHAR2(27), uniqueness VARCHAR2(9), status VARCHAR2(8), visibility VARCHAR2(9),\n  tablespace_name VARCHAR2(30), last_analyzed DATE);\nINSERT INTO dba_indexes VALUES\n  ('APP_VENTES', 'PK_VENTES', 'VENTES', 'NORMAL', 'UNIQUE', 'VALID', 'VISIBLE', 'APP_INDEX', '2026-10-27 22:14:00'),\n  ('APP_VENTES', 'PK_LIGNES_VENTES', 'LIGNES_VENTES', 'NORMAL', 'UNIQUE', 'VALID', 'VISIBLE', 'APP_INDEX', '2026-09-12 23:40:00'),\n  ('APP_VENTES', 'IDX_LIGNES_DATE', 'LIGNES_VENTES', 'NORMAL', 'NONUNIQUE', 'VALID', 'VISIBLE', 'APP_INDEX', '2026-09-12 23:52:00'),\n  ('APP_VENTES', 'IDX_LIGNES_PRODUIT', 'LIGNES_VENTES', 'NORMAL', 'NONUNIQUE', 'UNUSABLE', 'VISIBLE', 'APP_INDEX', '2026-09-12 23:58:00'),\n  ('APP_VENTES', 'IDX_VENTES_CLIENT', 'VENTES', 'NORMAL', 'NONUNIQUE', 'VALID', 'INVISIBLE', 'APP_INDEX', '2026-10-27 22:15:00'),\n  ('APP_VENTES', 'PK_CLIENTS', 'CLIENTS', 'NORMAL', 'UNIQUE', 'VALID', 'VISIBLE', 'APP_INDEX', '2026-10-25 22:03:00'),\n  ('APP_RH', 'PK_EMPLOYES', 'EMPLOYES', 'NORMAL', 'UNIQUE', 'VALID', 'VISIBLE', 'APP_INDEX', '2026-10-26 22:01:00'),\n  ('APP_RH', 'IDX_EMP_NOM_UPPER', 'EMPLOYES', 'FUNCTION-BASED NORMAL', 'NONUNIQUE', 'VALID', 'VISIBLE', 'APP_INDEX', '2026-10-26 22:01:00');\n\nCREATE TABLE dba_ind_columns (index_owner VARCHAR2(128), index_name VARCHAR2(128), table_name VARCHAR2(128),\n  column_name VARCHAR2(4000), column_position NUMBER);\nINSERT INTO dba_ind_columns VALUES\n  ('APP_VENTES', 'PK_VENTES', 'VENTES', 'ID_VENTE', 1),\n  ('APP_VENTES', 'PK_LIGNES_VENTES', 'LIGNES_VENTES', 'ID_VENTE', 1),\n  ('APP_VENTES', 'PK_LIGNES_VENTES', 'LIGNES_VENTES', 'NUM_LIGNE', 2),\n  ('APP_VENTES', 'IDX_LIGNES_DATE', 'LIGNES_VENTES', 'DATE_VENTE', 1),\n  ('APP_VENTES', 'IDX_LIGNES_PRODUIT', 'LIGNES_VENTES', 'PRODUIT', 1),\n  ('APP_VENTES', 'IDX_VENTES_CLIENT', 'VENTES', 'ID_CLIENT', 1),\n  ('APP_VENTES', 'PK_CLIENTS', 'CLIENTS', 'ID_CLIENT', 1),\n  ('APP_RH', 'PK_EMPLOYES', 'EMPLOYES', 'ID_EMPLOYE', 1),\n  ('APP_RH', 'IDX_EMP_NOM_UPPER', 'EMPLOYES', 'SYS_NC00012$', 1);\n\nCREATE TABLE dba_tab_statistics (owner VARCHAR2(128), table_name VARCHAR2(128), num_rows NUMBER, blocks NUMBER,\n  last_analyzed DATE, stale_stats VARCHAR2(3));\nINSERT INTO dba_tab_statistics VALUES\n  ('APP_VENTES', 'LIGNES_VENTES', 141000000, 4710000, '2026-09-12 23:40:00', 'YES'),\n  ('APP_VENTES', 'VENTES', 41200000, 1490000, '2026-10-27 22:14:00', 'NO'),\n  ('APP_VENTES', 'CLIENTS', 1850000, 112000, '2026-10-25 22:03:00', 'NO'),\n  ('APP_VENTES', 'AUDIT_LOG', NULL, NULL, NULL, NULL),\n  ('APP_RH', 'EMPLOYES', 3120, 5100, '2026-10-26 22:01:00', 'NO'),\n  ('APP_RH', 'SERVICES', 42, 5, '2025-02-11 22:00:00', 'NO'),\n  ('APP_RH', 'HISTO_PAIE', 2900000, 76000, '2026-10-26 22:05:00', 'NO');\n\n-- Niveau Senior ---------------------------------------------------------------\n\nCREATE TABLE dba_feature_usage_statistics (name VARCHAR2(128), version VARCHAR2(17), detected_usages NUMBER,\n  currently_used VARCHAR2(5), first_usage_date DATE, last_usage_date DATE);\nINSERT INTO dba_feature_usage_statistics VALUES\n  ('Automatic Workload Repository', '19.0.0.0.0', 371, 'TRUE', '2019-04-15 00:00:00', '2026-10-25 00:00:00'),\n  ('AWR Report', '19.0.0.0.0', 14, 'TRUE', '2024-02-02 00:00:00', '2026-10-25 00:00:00'),\n  ('ADDM', '19.0.0.0.0', 9, 'TRUE', '2024-02-02 00:00:00', '2026-10-18 00:00:00'),\n  ('SQL Tuning Advisor', '19.0.0.0.0', 3, 'TRUE', '2025-06-10 00:00:00', '2026-09-30 00:00:00'),\n  ('Real-Time SQL Monitoring', '19.0.0.0.0', 6, 'TRUE', '2025-06-10 00:00:00', '2026-10-11 00:00:00'),\n  ('Partitioning (user)', '19.0.0.0.0', 0, 'FALSE', NULL, NULL),\n  ('Real Application Clusters (RAC)', '19.0.0.0.0', 0, 'FALSE', NULL, NULL),\n  ('Active Data Guard - Real-Time Query on Physical Standby', '19.0.0.0.0', 0, 'FALSE', NULL, NULL),\n  ('Transparent Data Encryption', '19.0.0.0.0', 0, 'FALSE', NULL, NULL),\n  ('Advanced Index Compression', '19.0.0.0.0', 0, 'FALSE', NULL, NULL),\n  ('Oracle Utility Datapump (Export)', '19.0.0.0.0', 41, 'TRUE', '2019-05-02 00:00:00', '2026-10-21 00:00:00'),\n  ('Recovery Manager (RMAN)', '19.0.0.0.0', 2210, 'TRUE', '2019-04-20 00:00:00', '2026-10-28 00:00:00');\n")
